css:
#outer_wrapper,body{background-color:#0E0A08!important}
#inner_wrapper{background-color:#1A1310!important;border-radius:18px!important;border-top:5px solid #B8202F!important;overflow:hidden}
#template_container,#template_header,#body_content,#template_footer{background-color:#1A1310!important}
#template_header_image{padding:34px 32px 6px!important;text-align:center!important}
#template_header_image p{text-align:center!important}
#template_header{color:#F7EEE3!important}
#header_wrapper{padding:18px 32px 0!important}
#header_wrapper h1{color:#F7EEE3!important;text-align:center!important;font-size:30px!important;letter-spacing:-.5px!important}
#body_content_inner,#body_content_inner p,#body_content_inner td,#body_content_inner th,.td{color:#E9DCCD!important}
#body_content_inner h2,.email-order-detail-heading,.wc-product-name,h3,.address-title,#body_content_inner b,#body_content_inner strong{color:#F7EEE3!important}
.email-order-detail-heading span,.email-order-item-meta,.email-order-item-meta *,.wc-item-meta,.wc-item-meta *{color:#BFAE9F!important}
.amount,.amount *,.woocommerce-Price-amount,.woocommerce-Price-currencySymbol{color:#EFA54E!important}
.order-totals-total td,.order-totals-total td .amount{font-size:22px!important;color:#EFA54E!important}
.order-totals-total th{color:#F7EEE3!important}
.email-order-item-thumbnail img{border-radius:10px!important}
td,th{border-color:rgba(255,255,255,.12)!important}
.order_item td,.order-totals-last th,.order-totals-last td,.order-customer-note td,.email-order-item-thumbnail{border-bottom-color:rgba(255,255,255,.12)!important}
hr{border-top-color:rgba(255,255,255,.14)!important}
address,.address{color:#E9DCCD!important;border-color:rgba(255,255,255,.12)!important}
#body_content_inner a,a{color:#EFA54E!important}
.email-additional-content,.email-additional-content p{color:#BFAE9F!important}
#credit{border-top:1px solid rgba(255,255,255,.12)!important;padding:28px 22px 26px!important;color:#BFAE9F!important;background-color:#140E0C!important}
.dc-mfoot a,#credit a{color:#F7EEE3!important}
.dc-mtit{color:#EFA54E!important}
.wc-bacs-bank-details-heading,.wc-bacs-bank-details li{color:#E9DCCD!important}
#credit img,.dc-mfoot img{margin:0!important}
@media screen and (max-width:600px){.dc-mcol{display:block!important;width:100%!important;padding:0 4px 18px!important}#inner_wrapper{border-radius:0!important}}
